sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var GetAppRecord = x_snc_devtools.GetAppRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var IsUserHasRoleExactly = x_snc_devtools.IsUserHasRoleExactly;
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var Clone = x_snc_devtools.Clone;
	var RenderDate = x_snc_devtools.RenderDate;


	function GetParam(strParam)
	{
		var queryParams = request.queryParams;
		return x_snc_devtools.GetStringValue(x_snc_devtools.GetValue(queryParams,strParam));
	}

	function Error(strMessage,strDetails)
	{
		var myError = new sn_ws_err.ServiceError();
		myError.setStatus(200);
		myError.setMessage(strMessage);
		myError.setDetail(strDetails);
		response.setError(myError);	
	}

	if (IsUserHasRoleExactly('x_snc_stores.api') == false)
	{
		Error('User Not Authorized','');
		return;
	}

	if (IsActive() == false)
	{
		Error('INACTIVE','The Stores app is inactive.');
		return;
	}

	var strStoreIdentifier = GetParam('store');

	if (strStoreIdentifier == '')
	{
		Error('STORE_NOT_SPECIFIED','No Store is specified.');
		return;
	}


	var grStore = GetStoreRecord(strStoreIdentifier);
	if (IsValidRecord(grStore) == false)
	{
		Error('STORE_NOT_FOUND','The specified Store could not be found.');
		return;
	}

	if (grStore.active == false)
	{
		Error('STORE_INACTIVE','The specified Store is inactive.');
		return;
	}


	var body = {};
	body.message = 'SUCCESS';
	body.store = GetStore(grStore);

	var strDate = GetParam('date');

	if (strDate == '')
	{
		body.store.hours_rules = GetAllHoursRulesForStore(grStore);
	}
	else
	{
		if (RenderDate(strDate) != strDate)
		{
			Error('DATE_INVALID','The specified date is invalid. Use this format: "YYYY-MM-DD"!');
			return;			
		}
		body.store.hours_rules = GetActiveHoursRulesForStoreByDate(grStore,strDate);

	}

	response.setBody(body);

	return;

})(request, response);
